nextflow_process {

    name "Test Process DDS_CREATEPROJECT"
    script "../main.nf"
    process "DDS_CREATEPROJECT"

    tag "modules"
    tag "modules_nfcore"
    tag "dds"
    tag "dds/createproject"

    test("dds/createproject - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = ["Test title", "Test description", "test-pi@mail.com"]
                input[1] = file(params.modules_testdata_base_path + 'generic/txt/hello.txt')
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match()}
            )
        }
    }
}
